(()=>{
const cases=[["alert alert-info","Alert / info"],["alert alert-error","Alert / error"],["alert alert-warning","Alert / warning"],["alert alert-success","Alert / success"],["btn btn-error","Button / error"],["btn btn-success","Button / success"],["btn btn-primary","Button / primary"],["background-error-light","Utility / .background-error-light"],["background-info-light","Utility / .background-info-light"]];
function parts(c){return c.replace(/[^0-9,.]/g,"").split(",").map(Number)}
function lum(c){const m=parts(c);const f=(v)=>{v=v/255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)};return 0.2126*f(m[0])+0.7152*f(m[1])+0.0722*f(m[2])}
function cr(a,b){const l1=lum(a),l2=lum(b);const hi=Math.max(l1,l2),lo=Math.min(l1,l2);return Math.round(((hi+0.05)/(lo+0.05))*100)/100}
const host=document.createElement("div");host.style.position="absolute";host.style.left="-9999px";host.style.width="400px";document.body.appendChild(host);
const out={};
for(let i=0;i<cases.length;i++){const cls=cases[i][0],label=cases[i][1];
const el=document.createElement("div");el.className=cls;el.textContent="Sample message";host.appendChild(el);
const cs=getComputedStyle(el);const bg=cs.backgroundColor;const fg=cs.color;
const rec={fg:fg,bg:bg};
if(bg.indexOf("rgba(0, 0, 0, 0)")===-1&&bg!=="transparent"){rec.contrast=cr(fg,bg)}else{rec.contrast="no-own-background"}
out[label]=rec;}
host.remove();return out;})()

